def load_existing():
    """读取上一轮的内部元数据（含 hash）与倒排索引，用于增量。

    注意：必须读 meta_full.json 与 bm25.json——精简版 meta.json 为了压缩体积
    把页面存成了数组，不含 hash 字段。

    v2 索引（2026-10-04 起）只存倒排 `postings`，不再存每页的完整重复词序列；
    这里用 `tf_from_postings` 反推回 {页面名: {term: tf}} 供增量复用。
    同时兼容 v1（正排 `_tokens`），以免旧索引直接失效。
    """
    old = {"pages": {}, "doc_tf": {}, "doc_names": [], "postings": {}}
    if os.path.exists(K.FULL_PATH):
        try:
            with open(K.FULL_PATH, "r", encoding="utf-8") as f:
                old["pages"] = json.load(f).get("pages", {})
        except Exception:
            old["pages"] = {}
    if os.path.exists(K.BM25_PATH):
        try:
            with open(K.BM25_PATH, "r", encoding="utf-8") as f:
                bm = json.load(f)
            old["doc_names"] = bm.get("doc_names", [])
            old["postings"] = bm.get("postings", {})
            if old["postings"]:
                old["doc_tf"] = K.tf_from_postings(old["postings"], old["doc_names"])
            elif bm.get("_tokens"):
                old["doc_tf"] = {n: K.to_tf(t) for n, t in bm["_tokens"].items()}
        except Exception:
            pass
    return old


def scan_pages():
    """扫描全部页面，返回 {name: {fields, fm, path}}。

    🆕 2026-10-22：**项目文献卡一并入索引**（`projects/*/sources/`）。
    此前它们只存在于项目目录，`kb_search` / `kb_route` / `kb_graph` 完全看不见
    ——「卡已写好」不等于「检索得到」。
    ⚠️ 同名的 wiki 页**优先**：项目卡不得覆盖知识层页面。
    """
    pages = {}
    dup = []
    for path in K.iter_page_files(include_projects=True):
        if K.is_excluded(path):
            continue
        raw = K.read_text(path)
        fm_raw, body = K.split_frontmatter(raw)
        fm = K.parse_frontmatter(fm_raw)
        name = os.path.splitext(os.path.basename(path))[0]
        rel = os.path.relpath(path, K.VAULT).replace("\\", "/")
        if name in pages:
            if K.is_project_page(path):
                dup.append(name)
                continue
        fields = K.build_fields(name, fm, body)
        pages[name] = {"fields": fields, "fm": fm, "path": rel}
    if dup:
        print(f"[warn] {len(dup)} 张项目卡与 wiki 页同名，已保留 wiki 页：{dup[:3]}")
    return pages


def _build_meta_lite(meta_pages, alias_map):
    """生成 meta_lite.json：对每个页面仅保留 type/summary(截断100字)/tags/aliases/name。

    顶层按类型分组，与 meta.json 保持一致的目录结构：
      concepts/entities/topics/outputs  → {name: {type,s,t,a,n}}
      sources                           → [[name, summary_100, tags, aliases], ...]
      alias_map                         → 完整保留（搜索关键）
    """
    SUMMARY_LITE_LEN = 100

    groups = {"concept": {}, "entity": {}, "topic": {}, "output": {}}
    src_rows = []

    for name, m in sorted(meta_pages.items()):
        ptype = m.get("type", "")
        summary = m.get("summary", "") or ""
        tags = m.get("tags", []) or []
        aliases = m.get("aliases", []) or []
        s_lite = summary[:SUMMARY_LITE_LEN] + ("..." if len(summary) > SUMMARY_LITE_LEN else "")

        if ptype == "source":
            src_rows.append([name, s_lite, tags, aliases])
        else:
            entry = {"type": ptype, "s": s_lite, "t": tags, "a": aliases, "n": name}
            bucket = groups.get(ptype)
            if bucket is not None:
                bucket[name] = entry
            else:
                groups["output"][name] = entry

    return {
        "concepts": groups["concept"],
        "entities": groups["entity"],
        "sources": src_rows,
        "topics": groups["topic"],
        "outputs": groups["output"],
        "alias_map": alias_map,
    }


def write_page_fm(meta_pages):
    """把预取的 frontmatter 限定词写入独立侧车 `meta_fm.json`（2026-10-15）。

    只收**有内容**的页——多数页没有 source_reliability，写空 dict 纯属浪费体积。
    """
    page_fm = {n: m["fm"] for n, m in meta_pages.items() if m.get("fm")}
    os.makedirs(K.INDEX_DIR, exist_ok=True)
    K.write_json_atomic(K.META_FM_PATH, {
        "_generated_by": "tools/kb_build_index.py",
        "_note": ("预取的 frontmatter 限定词（source_reliability / evidence_base / "
                  "si_status），供检索层免去逐页读盘。"
                  "**刻意与 meta.json 分开**：后者是 AI 每次查询整份读入的文件。"),
        "fields": list(K.FM_INDEX_FIELDS),
        "count": len(page_fm),
        "page_fm": page_fm,
    }, ensure_ascii=False, separators=(",", ":"))
    return len(page_fm)


def add_pages(page_rel_paths, also_lite=False):
    """增量模式：仅对指定页面计算 BM25 并合并到现有索引。

    page_rel_paths: 相对于 wiki/ 的路径列表
    """
    from collections import defaultdict

    # ---- 加载现有 bm25.json
    bm25_data = {}
    if os.path.exists(K.BM25_PATH):
        try:
            with open(K.BM25_PATH, "r", encoding="utf-8") as f:
                bm25_data = json.load(f)
        except Exception:
            pass
    if not bm25_data:
        print("[!] 现有 bm25.json 不存在或为空，请先运行全量构建：")
        print("    python tools/kb_build_index.py")
        return 1

    # 取出现有 doc→tf（v2 走 postings 反推，v1 走 _tokens）
    doc_names_old = bm25_data.get("doc_names", [])
    if bm25_data.get("postings"):
        doc_tf = K.tf_from_postings(bm25_data["postings"], doc_names_old)
    else:
        doc_tf = {n: K.to_tf(t) for n, t in bm25_data.get("_tokens", {}).items()}

    # ---- 加载现有 meta_full.json
    full_pages = {}
    if os.path.exists(K.FULL_PATH):
        try:
            with open(K.FULL_PATH, "r", encoding="utf-8") as f:
                full_pages = json.load(f).get("pages", {})
        except Exception:
            pass

    # ---- 加载现有 meta.json
    meta = {}
    if os.path.exists(K.META_PATH):
        try:
            with open(K.META_PATH, "r", encoding="utf-8") as f:
                meta = json.load(f)
        except Exception:
            pass

    # ---- 是否需要维护 meta_lite.json
    # 2026-10-15：**只判存在，不再 json.load**。旧版把整个 712 KB 读进来，却只用来判断
    #   「该不该重写它」——内容一个字段都没用上。而它**没有任何下游消费者**
    #   （见文件头说明）。白白解析 712 KB 属纯浪费。
    meta_lite = (also_lite and os.path.exists(K.META_LITE_PATH)) or None

    fresh, reused = 0, 0
    seen_names = set()
    alias_map = meta.get("alias_map", {})

    for rel_path in page_rel_paths:
        # 🆕 2026-10-22：`projects/...` 视为**库根相对**（项目卡不在 wiki/ 下）；
        # 其余仍按 wiki 相对。写作 `path` 时统一成库根相对，与全量构建一致。
        rel_norm = rel_path.replace("\\", "/")
        is_proj = rel_norm.startswith("projects/")
        full_path = os.path.join(K.VAULT if is_proj else K.WIKI, rel_path)
        if not os.path.exists(full_path):
            print(f"  [!] 文件不存在，跳过: {rel_path}")
            continue

        name = os.path.splitext(os.path.basename(rel_path))[0]

        # 去重：同一名称多次指定时只处理最后一次
        if name in seen_names:
            continue
        seen_names.add(name)

        raw = K.read_text(full_path)
        fm_raw, body = K.split_frontmatter(raw)
        fm = K.parse_frontmatter(fm_raw)
        fields = K.build_fields(name, fm, body)

        h = K.content_hash(fields)
        # 重算该页的 tf（增量只改这一页；倒排索引在所有页面处理完后统一重建）
        doc_tf[name] = K.to_tf(K.weighted_tokens(fields))
        fresh += 1

        # ---- 更新 meta_full.json
        full_pages[name] = {
            "type": fm.get("type", ""),
            "summary": fm.get("summary", "") or "",
            "tags": fm.get("tags", []) or [],
            "aliases": fm.get("aliases", []) or [],
            "updated": fm.get("updated", ""),
            "terms": K.top_terms(fields),
            "out": K.extract_outlinks(raw),
            "n_sources": len(fm.get("sources", []) or []),
            "path": rel_norm if is_proj else "wiki/" + rel_norm,
            "hash": h,
            "fm": K.index_fm_extras(fm),      # 🆕 预取限定词字段（诊断 P1-4）
        }

        # ---- 更新 alias_map：移除旧别名，添加新别名
        for k, v in list(alias_map.items()):
            if v == name:
                del alias_map[k]
        aliases = fm.get("aliases", []) or []
        if isinstance(aliases, str):
            aliases = [aliases]
        pages_for_alias = {name: {"aliases": aliases, "type": fm.get("type", "")}}
        new_aliases = K.build_alias_map(pages_for_alias)
        alias_map.update(new_aliases)

    if not seen_names:
        print("[!] 未找到任何有效页面")
        return 1

    # 重建倒排索引（相对 583 页规模，整表重建只需毫秒级；
    # 比手工做 posting 级增删更不容易出错——写盘脚本铁律：宁慢勿错）
    doc_names = sorted(doc_tf.keys())
    postings, df = K.build_postings(doc_tf, doc_names)
    # 应用与全量构建相同的噪声过滤（df 与 postings 必须同步剔除）
    df = {t: c for t, c in df.items() if not (c == 1 and len(t) > 20)}
    postings = {t: v for t, v in postings.items() if t in df}
    doc_len = {n: sum(doc_tf[n].values()) for n in doc_names}

    # ---- 写回 bm25.json
    bm25 = {
        "_version": 2,
        "_note": ("BM25 倒排索引：postings = {term: [[doc_idx, tf], ...]}，"
                  "doc_len 用于长度归一化，df = 文档频率。"),
        "doc_names": doc_names,
        "doc_len": doc_len,
        "df": df,
        "n_docs": len(doc_names),
        "postings": postings,
    }
    os.makedirs(K.INDEX_DIR, exist_ok=True)
    K.write_json_atomic(K.BM25_PATH, bm25, ensure_ascii=False, separators=(",", ":"))

    # ---- 写回 meta_full.json
    full = {
        "_note": "内部元数据，含出链与内容 hash。AI 查询无需读取。",
        "pages": full_pages,
    }
    K.write_json_atomic(K.FULL_PATH, full, ensure_ascii=False, separators=(",", ":"))

    # ---- 更新 meta.json
    if meta:
        lean_pages, src_rows = K.group_by_type(full_pages)
        meta["alias_map"] = alias_map
        meta["count"] = len(full_pages)
        meta["pages"] = lean_pages
        meta["sources"] = src_rows
        # 🆕 侧车同步（2026-10-15）：**同一份真源重写整个文件**，不做增量合并。
        #    侧车 252 KB、862 页，整体重写是毫秒级；而增量合并要处理「旧条目缺 fm 键」
        #    的过渡态，正是本库最忌讳的「静默错位」来源 —— 宁慢勿错。
        #    `full_pages` 旧条目可能没有 "fm" 键（本次改动前建的索引）⇒ m.get 兜底。
        write_page_fm(full_pages)
        # 旧版把 page_fm 内嵌在 meta.json；现改侧车 ⇒ 显式**移除**内嵌键，
        # 否则旧索引的 252 KB 会一直留在 AI 阅读路径上（拆分等于没做）。
        meta.pop("page_fm", None)
        K.write_json_atomic(K.META_PATH, meta, ensure_ascii=False, separators=(",", ":"))

    # ---- 更新 meta_lite.json（如已有或 --lite 同时指定）
    if meta_lite is not None:
        # 需要从 full_pages 重建 meta_pages 格式以传给 _build_meta_lite
        meta_pages_for_lite = {}
        for n, m in full_pages.items():
            meta_pages_for_lite[n] = {
                "type": m.get("type", ""),
                "summary": m.get("summary", ""),
                "tags": m.get("tags", []),
                "aliases": m.get("aliases", []),
            }
        lite = _build_meta_lite(meta_pages_for_lite, alias_map)
        K.write_json_atomic(K.META_LITE_PATH, lite, ensure_ascii=False, separators=(",", ":"))

    print(f"[OK] 增量更新：{len(seen_names)} 个页面（重算 {fresh}）")
    print(f"     索引总页面: {len(doc_names)}")
    sz_b = os.path.getsize(K.BM25_PATH) / 1024
    print(f"     bm25.json  : {sz_b:.0f} KB")
    return 0


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    本脚本的产物是**派生数据**（`.index/`），故自检不可能是「重建一次再比」，
    而是钉住**索引自身的内部一致性**——因为下游（`kb_search`）的全部正确性
    都建立在这些不变量之上，而它们一旦破了，**不会有任何报错，只会静默漏检**。
    """
    import os as _os
    import json as _json
    ok = True

    p = K.BM25_PATH
    ex = _os.path.exists(p)
    print(f"  [{'ok' if ex else 'FAIL'}] bm25.json 存在")
    if not ex:
        print("=== selftest FAIL ===")
        return 1
    bm = _json.load(open(p, encoding="utf-8"))
    postings = bm.get("postings") or {}
    df = bm.get("df") or {}
    doc_names = bm.get("doc_names") or []
    doc_len = bm.get("doc_len") or []
    n_docs = bm.get("n_docs")

    # ① 版本必须是 v2 倒排（v1 正排已废弃；版本写错下游会找不到 postings）
    good = bm.get("_version") == 2
    print(f"  [{'ok' if good else 'FAIL'}] 索引版本为 v2 倒排 -> {bm.get('_version')}")
    ok = ok and good

    # ② postings 与 df **必须同步剔除**词项（本脚本注释明载的坑）。
    #    若 postings 里还留着 df 没有的词，打分时会出现「有倒排但无 df」⇒ 静默错分。
    missing_df = set(postings) - set(df)
    good = not missing_df
    print(f"  [{'ok' if good else 'FAIL'}] postings ⊆ df（同步剔除已生效）"
          f" -> 越界 {len(missing_df)} 个")
    ok = ok and good
    only_df = set(df) - set(postings)
    print(f"  [info] df 有而 postings 无 {len(only_df)} 个词（允许，仅提示）")

    # ③ 三个数组长度必须一致，且与 n_docs 相符
    good = len(doc_names) == len(doc_len) and (n_docs in (None, len(doc_names)))
    print(f"  [{'ok' if good else 'FAIL'}] doc_names/doc_len/n_docs 一致 -> "
          f"names={len(doc_names)} len={len(doc_len)} n_docs={n_docs}")
    ok = ok and good

    # ④ 每个 posting 的 doc_idx 必须落在 [0, n_docs)——越界会让打分静默取错文档
    bad_idx = sum(1 for plist in postings.values() for it in plist
                  if not it or not isinstance(it[0], int)
                  or not (0 <= it[0] < len(doc_names)))
    good = bad_idx == 0
    print(f"  [{'ok' if good else 'FAIL'}] 全部 doc_idx 在合法范围内 -> 越界 {bad_idx}")
    ok = ok and good

    # ⑤ tf 必须为正整数（tf<=0 会让 BM25 打分静默归零）
    bad_tf = sum(1 for plist in postings.values() for it in plist
                 if len(it) < 2 or not isinstance(it[1], int) or it[1] <= 0)
    good = bad_tf == 0
    print(f"  [{'ok' if good else 'FAIL'}] 全部 tf 为正整数 -> 异常 {bad_tf}")
    ok = ok and good

    # ⑥ 库内有页面 ⇒ 索引必须非空（空索引会让查询静默漏检）；
    #    库内本就 0 页面 ⇒ 空索引是**正确**产物（2026-10-11 起支持空库启动），跳过。
    try:
        _has_pages = any(K.iter_page_files())
    except Exception:                                      # noqa: BLE001
        _has_pages = True
    if _has_pages:
        good = len(postings) > 0 and len(doc_names) > 0
        print(f"  [{'ok' if good else 'FAIL'}] 反例 索引非空（库内有页面）-> "
              f"{len(postings)} 词 / {len(doc_names)} 文档")
        ok = ok and good
    else:
        print("  [skip] 空库：空索引为正确产物（Stage 0 起）")

    # ⑦ 交叉断言：与 kb_lib.tf_from_postings 反推结果一致（同一份数据的两个消费者）
    try:
        tf = K.tf_from_postings(postings, doc_names)
        good = isinstance(tf, dict) and len(tf) == len(doc_names)
        print(f"  [{'ok' if good else 'FAIL'}] tf_from_postings 反推文档数一致 -> "
              f"{len(tf) if isinstance(tf, dict) else 'ERR'}")
        ok = ok and good
    except Exception as e:                       # noqa: BLE001
        print(f"  [FAIL] tf_from_postings 抛错: {e}")
        ok = False

    # ⑧ 回归夹具（2026-10-11）：空库必须能建出**合法空索引**，且 kb_search
    #   不得 exit(2)。起因：0 页面时 main() 曾在 makedirs 之前 return 1 ⇒ 一个
    #   索引文件都不写 ⇒ kb_search.load_index() sys.exit(2) ⇒ 全新克隆的库连
    #   主检索入口都起不来。此夹具钉死该修复（正例：空库 exit 0 + 三文件合法 +
    #   search 不 exit 2）。
    ok = _empty_vault_fixture() and ok

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def _empty_vault_fixture():
    """在临时目录造一个 0 页面的空库，跑 kb_build_index + kb_search，断言优雅。"""
    import tempfile
    import shutil
    import subprocess
    try:
        with K.temp_dir() as td:
            shutil.copytree(os.path.dirname(os.path.abspath(__file__)),
                            os.path.join(td, "tools"))
            for d in ("wiki/concepts", "wiki/entities", "wiki/sources",
                      "wiki/topics", "wiki/outputs", "raw/pdf", "raw/text"):
                os.makedirs(os.path.join(td, d), exist_ok=True)
            env = dict(os.environ, PYTHONIOENCODING="utf-8")
            bi = subprocess.run(
                [__import__("sys").executable,
                 os.path.join(td, "tools", "kb_build_index.py")],
                capture_output=True, text=True, encoding="utf-8",
                errors="replace", cwd=td, env=env)
            # 🆕 2026-10-15：`meta_fm.json` 侧车也必须在四件套里 —— 它是检索层
            #    取可靠性限定词的来源，缺了 L2 就会静默丢限定词（本库最忌的失效形态）。
            _need = ("meta.json", "meta_full.json", "bm25.json", "meta_fm.json")
            wrote = all(os.path.exists(os.path.join(td, "wiki", ".index", f))
                        for f in _need)
            missing = [f for f in _need
                       if not os.path.exists(os.path.join(td, "wiki", ".index", f))]
            good_build = bi.returncode == 0 and wrote
            print(f"  [{'ok' if good_build else 'FAIL'}] 空库构建：exit={bi.returncode}"
                  f" 索引四件套={'齐' if wrote else '缺 ' + str(missing)}")
            sr = subprocess.run(
                [__import__("sys").executable,
                 os.path.join(td, "tools", "kb_search.py"), "x"],
                capture_output=True, text=True, encoding="utf-8",
                errors="replace", cwd=td, env=env)
            good_search = sr.returncode == 0          # 关键：不是 exit 2
            print(f"  [{'ok' if good_search else 'FAIL'}] 空库检索不 exit(2)："
                  f"exit={sr.returncode}")
            return good_build and good_search
    except Exception as e:                            # noqa: BLE001
        print(f"  [FAIL] 空库夹具异常: {e}")
        return False



def main():
    # `--help` 的 description/help 文本含 ✅ 等非 GBK 字符；CP936 控制台下
    # print 会抛 UnicodeEncodeError ⇒ 退出码 1（2026-10-23 修复）。
    K.console_encoding()
    ap = argparse.ArgumentParser()
    ap.add_argument("--full", action="store_true", help="全量重建，忽略增量缓存")
    ap.add_argument("--stats", action="store_true", help="只打印统计")
    ap.add_argument("--lite", action="store_true",
                    help="额外生成 meta_lite.json（⚠️ 目前无工具读取它，见文件头说明）")
    ap.add_argument("--add", nargs="+", metavar="PAGE",
                    help="增量添加/更新指定页面（相对于 wiki/ 的路径）")
    ap.add_argument("--embed", action="store_true",
                    help="同时构建嵌入索引（语义检索，需 sentence-transformers 或 scikit-learn）")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    # ---- 增量添加模式
    if args.add:
        ret = add_pages(args.add, also_lite=args.lite)
        if ret == 0 and args.embed:
            _build_embed_incremental(args.add)
        return ret

    pages = scan_pages()
    if not pages:
        # 空库（0 页面）也必须落一个**合法的空索引**：
        #   否则 kb_search.load_index() 会 sys.exit(2)，而 kb_route / kb_graph /
        #   kb_backlinks / kb_serve / kb.py --doctor 全走这条路 ⇒ 全新克隆的库
        #   连主检索入口都起不来。空索引让下游优雅退化为 low_confidence 空包。
        # 直接走下方**同一个写入器**（pages 为空时各 helper 天然产出空集合），
        #   以保证空索引与非空索引 schema 完全一致——不另抄一份书写逻辑。
        print("[i] 未找到任何页面（空库）；将写入合法空索引")

    # ---- 增量：判断哪些页面需要重算 tf
    old = {} if args.full else load_existing()
    old_pages = old.get("pages", {})
    old_doc_tf = old.get("doc_tf", {})

    fresh, reused = 0, 0
    doc_tf = {}
    for name, p in pages.items():
        h = K.content_hash(p["fields"])
        p["hash"] = h
        prev = old_pages.get(name)
        if prev and prev.get("hash") == h and name in old_doc_tf:
            doc_tf[name] = old_doc_tf[name]
            reused += 1
        else:
            doc_tf[name] = K.to_tf(K.weighted_tokens(p["fields"]))
            fresh += 1

    # ---- 别名映射
    alias_map = K.build_alias_map({n: {"aliases": p["fm"].get("aliases") or [],
                                       "type": p["fm"].get("type", "")}
                                   for n, p in pages.items()})

    # ---- 组装 meta.json（AI 读的那份，尽量紧凑）
    meta_pages = {}
    for name, p in pages.items():
        fm = p["fm"]
        aliases = fm.get("aliases") or []
        tags = fm.get("tags") or []
        sources = fm.get("sources") or []
        if isinstance(aliases, str):
            aliases = [aliases]
        if isinstance(tags, str):
            tags = [tags]
        if isinstance(sources, str):
            sources = [sources]
        meta_pages[name] = {
            "type": fm.get("type", ""),
            "summary": fm.get("summary", "") or "",
            "tags": tags,
            "aliases": aliases,
            "updated": fm.get("updated", ""),
            "terms": K.top_terms(p["fields"]),
            "out": K.extract_outlinks(K.read_text(os.path.join(K.VAULT, p["path"]))),
            "n_sources": len(sources),
            "path": p["path"],
            "hash": p["hash"],
            "fm": K.index_fm_extras(fm),      # 🆕 预取限定词字段（诊断 P1-4）
        }

    # ---- 倒排索引（真正的 inverted index：term → [[doc_idx, tf], ...]）
    doc_names = sorted(doc_tf.keys())
    postings, df = K.build_postings(doc_tf, doc_names)

    # 精简：丢弃只出现 1 次且长度 > 20 的超长稀有词（噪声）
    #   df 与 postings 必须**同步**剔除，否则打分时 postings 里还留着 df 没有的词，
    #   会给它们算出偏高的 idf。
    df = {t: c for t, c in df.items() if not (c == 1 and len(t) > 20)}
    postings = {t: v for t, v in postings.items() if t in df}

    doc_len = {n: sum(doc_tf[n].values()) for n in doc_names}

    if args.stats:
        print(f"页面总数      : {len(pages)}")
        print(f"新增/重算     : {fresh}")
        print(f"复用缓存      : {reused}")
        print(f"别名条目      : {len(alias_map)}")
        print(f"词表大小      : {len(df)}")
        by_type = defaultdict(int)
        for m in meta_pages.values():
            by_type[m["type"] or "?"] += 1
        for t, c in sorted(by_type.items(), key=lambda kv: -kv[1]):
            print(f"  {t:<10}: {c}")
        return 0

    os.makedirs(K.INDEX_DIR, exist_ok=True)

    # ---- 精简版：AI 每次查询读入的那份
    lean_pages, src_rows = K.group_by_type(meta_pages)
    # 🆕 预取的 frontmatter 限定词（诊断 P1-4）写入**独立侧车** meta_fm.json（2026-10-15）。
    #    不放进 meta.json：那是 AI 每次查询整份读入的文件，252 KB 的限定词会让它 +26%。
    #    侧车只在检索层真正要用时加载一次 —— 仍是 O(1) IO，而 meta.json 回到改造前体积。
    #    另注：**不能加进 PAGE_COLS/SOURCE_COLS**，那两组是位置元组，加列会让按位解包静默错位。
    write_page_fm(meta_pages)
    meta = {
        "_generated_by": "tools/kb_build_index.py",
        "_note": "AI 检索用元数据。查询时先整份读入，再对候选页做 BM25 精排。",
        "_schema": {
            "pages": f"{{页面名: {K.PAGE_COLS}}}（非来源页面）",
            "source_cols": K.SOURCE_COLS,
            "alias_map": "{别名小写: 规范页面名}",
            "page_fm": f"**已移出本文件** -> {os.path.basename(K.META_FM_PATH)}"
                       "（预取的 frontmatter 限定词，检索层按需加载）",
        },
        "count": len(pages),
        "alias_map": alias_map,
        "pages": lean_pages,
        "source_cols": K.SOURCE_COLS,
        "sources": src_rows,
    }
    K.write_json_atomic(K.META_PATH, meta, ensure_ascii=False, separators=(",", ":"))

    # ---- 内部版：出链/路径/hash，供工具与补链分析用
    full = {
        "_note": "内部元数据，含出链与内容 hash。AI 查询无需读取。",
        "pages": {n: m for n, m in meta_pages.items()},
    }
    K.write_json_atomic(K.FULL_PATH, full, ensure_ascii=False, separators=(",", ":"))

    bm25 = {
        "_version": 2,
        "_note": ("BM25 倒排索引：postings = {term: [[doc_idx, tf], ...]}，"
                  "doc_len 用于长度归一化，df = 文档频率。"
                  "v1 的正排 _tokens 已废弃（体积大且打分需线性扫描）。"),
        "doc_names": doc_names,
        "doc_len": doc_len,
        "df": df,
        "n_docs": len(doc_names),
        "postings": postings,
    }
    K.write_json_atomic(K.BM25_PATH, bm25, ensure_ascii=False, separators=(",", ":"))

    # 原来的 old 里可能包含已删除页面，这里以磁盘为准，天然清理
    removed = set(old_pages) - set(pages)
    added = set(pages) - set(old_pages)

    # ---- meta_lite.json（--lite 时额外输出）
    if args.lite:
        lite = _build_meta_lite(meta_pages, alias_map)
        K.write_json_atomic(K.META_LITE_PATH, lite, ensure_ascii=False, separators=(",", ":"))
        sz_l = os.path.getsize(K.META_LITE_PATH) / 1024
        print(f"     meta_lite.json   : {sz_l:.0f} KB  (--lite 精简索引)")

    sz_m = os.path.getsize(K.META_PATH) / 1024
    sz_b = os.path.getsize(K.BM25_PATH) / 1024
    sz_f = os.path.getsize(K.FULL_PATH) / 1024
    print(f"[OK] 索引已更新：{len(pages)} 页（重算 {fresh} / 复用 {reused}）")
    print(f"     meta.json      : {sz_m:.0f} KB  <- AI 每次查询读这份")
    print(f"     bm25.json      : {sz_b:.0f} KB")
    print(f"     meta_full.json : {sz_f:.0f} KB  (工具内部用)")
    if added:
        print(f"     新增 {len(added)}: {', '.join(sorted(added)[:8])}" +
              (" ..." if len(added) > 8 else ""))
    if removed:
        print(f"     移除 {len(removed)}: {', '.join(sorted(removed)[:8])}" +
              (" ..." if len(removed) > 8 else ""))

    # ---- 嵌入索引（--embed）
    if args.embed:
        print()
        _build_embed_full()

    return 0


def _build_embed_full():
    """调用 kb_semantic_search 全量构建嵌入索引。"""
    try:
        import kb_semantic_search as SEM
        backend = SEM.detect_backend()
        if backend is None:
            print("[!] 嵌入构建跳过：无可用后端（需 sentence-transformers 或 scikit-learn）")
            return
        print(f"[嵌入] 后端: {'sentence-transformers' if backend == 'st' else 'TF-IDF + SVD (降级)'}")
        SEM.build_embeddings()
    except Exception as e:
        print(f"[!] 嵌入构建失败: {e}")


def _build_embed_incremental(page_rel_paths):
    """调用 kb_semantic_search 增量更新嵌入索引。"""
    try:
        import kb_semantic_search as SEM
        backend = SEM.detect_backend()
        if backend is None:
            print("[!] 嵌入更新跳过：无可用后端")
            return
        SEM.add_embeddings(page_rel_paths)
    except Exception as e:
        print(f"[!] 嵌入增量更新失败: {e}")


if __name__ == "__main__":
    sys.exit(main())
